import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    success = True
    failed_files = []

    if not os.path.exists(src_folder):
        return {'success': False, 'message': f'Source folder {src_folder} does not exist', 'failed_files': []}

    if not os.path.exists(dst_folder):
        try:
            os.makedirs(dst_folder)
        except Exception:
            return {'success': False, 'message': f'Failed to create destination folder {dst_folder}', 'failed_files': []}

    files = glob(os.path.join(src_folder, '*'))

    for file_path in files:
        if os.path.isfile(file_path):
            filename = os.path.basename(file_path)
            try:
                result = subprocess.run(['gzip', file_path], capture_output=True, timeout=30)
                if result.returncode != 0:
                    failed_files.append(filename)
                    success = False
                    continue

                compressed_file = file_path + '.gz'
                if not os.path.exists(compressed_file):
                    failed_files.append(filename)
                    success = False
                    continue

                dest_path = os.path.join(dst_folder, filename + '.gz')
                shutil.move(compressed_file, dest_path)
            except Exception:
                failed_files.append(filename)
                success = False

    if success:
        return {'success': True, 'message': 'All files compressed and moved successfully', 'failed_files': []}
    else:
        return {'success': False, 'message': f'Failed to process {len(failed_files)} file(s)', 'failed_files': failed_files}
